sys_security_acl.script:
// Admins can edit any assessment
if (gs.hasRole('x_1879300_learning.admin')) {
    return true;
}

// Instructors can modify assessments for their courses
if (gs.hasRole('x_1879300_learning.instructor')) {
    // Check course ownership for lesson quizzes
    if (current.lesson) {
        var lessonGR = new GlideRecord('x_1879300_learning_lessons');
        if (lessonGR.get(current.lesson)) {
            var courseGR = new GlideRecord('x_1879300_learning_courses');
            if (courseGR.get(lessonGR.course)) {
                return courseGR.getValue('created_by') == gs.getUserID();
            }
        }
    }
    // Check course ownership for final exams
    if (current.course) {
        var courseGR = new GlideRecord('x_1879300_learning_courses');
        if (courseGR.get(current.course)) {
            return courseGR.getValue('created_by') == gs.getUserID();
        }
    }
}

// TAs can only update grading-related fields (handled by field-level ACLs)
return gs.hasRole('x_1879300_learning.teaching_assistant');
